using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF Core 9 renamed "Discriminator" to "$type".
            // Existing documents use "Discriminator", so we must explicitly preserve it.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change 2: EF Core 9 changed id format from "EntityType|Key" to just "Key".
            // Existing documents use "Blog|<key>" format, so we must preserve it.
            entity.Property(b => b.Id)
                .HasValueGeneratorFactory<LegacyIdValueGeneratorFactory>();

            // Breaking change 3: Cosmos DB does not support indexes defined via EF Core.
            // EF 9 now throws instead of silently ignoring. HasIndex removed.
        });
    }
}

// Generates ids in the legacy "Discriminator|Key" format for backward compat.
class LegacyIdValueGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
        => $"{entry.Metadata.ShortName()}|{Guid.NewGuid()}";
}

class LegacyIdValueGeneratorFactory : ValueGeneratorFactory
{
    public override ValueGenerator Create(IProperty property, IEntityType entityType)
